const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
const files=['app.js','engine.js','mixer-curves.js','fixtures.js','panels.js','deck-midi.js','eq-boost-harness.js'];
const identities=async()=>Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f,{cache:'no-store'})).arrayBuffer())])));
const click=s=>{assert($(s),'Missing '+s);$(s).click();},change=(s,v)=>{const e=$(s);assert(e,'Missing '+s);e.value=String(v);e.dispatchEvent(new Event('change',{bubbles:true}));},input=(s,v)=>{const e=$(s);assert(e,'Missing '+s);e.value=String(v);e.dispatchEvent(new Event('input',{bubbles:true}));};
async function until(fn,label){const end=performance.now()+20000;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
function base64(bytes){let s='';for(let n=0;n<bytes.length;n+=16384)s+=String.fromCharCode(...bytes.subarray(n,n+16384));return btoa(s);}
function amplitude(a,sr,from,to,hz){let re=0,im=0;const start=Math.ceil(from*sr),end=Math.floor(to*sr);assert(start>=0&&end<=a.length&&end>start,'Invalid fixed audio window');for(let n=start;n<end;n++){re+=a[n]*Math.cos(2*Math.PI*hz*n/sr);im+=a[n]*Math.sin(2*Math.PI*hz*n/sr);}return 2*Math.hypot(re,im)/(end-start);}
let app;
function output(r){$('#eq-original').textContent=JSON.stringify(r,null,2);$('#eq-results').textContent=JSON.stringify({...r,recording:r.recording?{...r.recording,base64:'Retained in complete original'}:null},null,2);$('#eq-status').textContent=r.completed?'Scoped EQ audio and reload checks passed':r.errors.length?'Failed: '+r.errors.map(e=>e.message).join('; '):'Recorded EQ audio; ready for reload';}
async function run(){
 const {state,engine}=app,r={startedAt:new Date().toISOString(),completed:false,scope:'Actual mixer/Setup/MIDI-editor range changes with owned three-tone fixture and full reload. Existing independent Web Audio EQ, not exact vendor filters/native/hardware acceptance.',criteria:{fixedSettlingSeconds:.25,fixedWindowSeconds:.4,maximumAbsoluteDecibelError:.45,minimumBaselineAmplitude:.003},cases:[],errors:[]};$('#eq-run').disabled=true;
 const bands=['low','mid','high'],mixer=()=>{click('[data-panel="settings"]');click('[data-settings-tab="Mixer"]');},boost=v=>change('[data-setting="EQ Boost"]',`${v} dB`),slider=band=>`[data-mix="0:${band}"]`;
 try{
  r.sourceBefore=await identities();await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Physical graph mute');await until(()=>!state.analysis,'Initial analysis');
  for(const d of state.decks)engine.pause(d);for(const bank of state.fx)for(const slot of bank)slot.on=false;engine.configureFX(state.fx,state.fxRoutes||[],state.decks.map(()=>120),state.fxTempo);
  const sr=48000,duration=40,d=state.decks[0],b=engine.ctx.createBuffer(2,sr*duration,sr);r.frequencies=[50,1000,12000];for(let c=0;c<2;c++){const a=b.getChannelData(c);for(let n=0;n<a.length;n++)for(const hz of r.frequencies)a[n]+=.02*Math.sin(2*Math.PI*hz*n/sr);}Object.assign(d.track,{bpm:120,grid:0,gridWarpMarkers:[],gridMarkers:[],duration,analyzed:true});Object.assign(d,{rate:1,position:0,keylock:false,keyShift:0,reverse:false,loop:true,loopIn:0,loopOut:duration,slip:false,stemSlip:'off',sync:false,level:.8,trim:1,low:0,mid:0,high:0,filter:0});engine.buffers.set(d.track.id,b);engine.mix(0,'level',.8);engine.mix(0,'trim',1);for(const band of bands)engine.mix(0,band,0);
  mixer();click('#reset-settings');click('#save-settings');input('#crossfader',0);click('[data-deck="0"][data-action="play"]');await until(()=>d.playing,'Actual Play');await engine.recordStart();r.recordStart=engine.recordStarted;
  async function sample(name,expectedDB,action){await action();const at=engine.ctx.currentTime-engine.recordStarted,c={name,expectedDB:[...expectedDB],at,from:at+.25,to:at+.65,boost:engine.eqBoost,state:bands.map(k=>d[k]),targets:structuredClone(engine.nodes[0].eqTargets),sliders:bands.map(k=>({value:Number($(slider(k)).value),max:Number($(slider(k)).max)}))};r.cases.push(c);assert(c.state.every((v,i)=>v===c.targets[bands[i]]&&Math.abs(v-c.sliders[i].value)<1e-8),'State, audio target and slider must agree');assert(c.sliders.every(s=>s.max===engine.eqBoost),'All GUI maxima match live range');await until(()=>engine.ctx.currentTime>=engine.recordStarted+c.to+.04,name);}
  await sample('neutral baseline',[0,0,0],async()=>{});
  for(const [i,band]of bands.entries()){
   const expected=Array(3).fill(0);expected[i]=6;await sample(`${band} GUI +6`,expected,async()=>input(slider(band),6));mixer();expected[i]=12;await sample(`${band} live 6 to12`,[...expected],async()=>boost(12));expected[i]=6;await sample(`${band} live12 to6`,[...expected],async()=>boost(6));click('#save-settings');input(slider(band),0);
  }
  mixer();boost(12);click('#save-settings');click('[data-panel="midi"]');click('#midi-reset');
  for(const [number,encoding]of [[20,'7-bit absolute'],[21,'Relative two’s complement']]){for(const [id,v]of [['#midi-target','Deck 1 mid'],['#midi-type','CC'],['#midi-channel',3],['#midi-number',number],['#midi-encoding',encoding]])$(id).value=String(v);click('#midi-add');}
  const send=(number,value)=>{for(const [id,v]of [['#midi-type','CC'],['#midi-channel',3],['#midi-number',number],['#midi-test-value',value]])$(id).value=String(v);click('#midi-send');};
  await sample('MIDI absolute maximum12',[0,12,0],async()=>send(20,127));await sample('MIDI relative minus half',[0,11.5,0],async()=>send(21,127));click('#modal-close');mixer();await sample('range change preserves fractional knob position',[0,5.75,0],async()=>boost(6));click('#save-settings');
  click('[data-panel="midi"]');await sample('MIDI center is neutral',[0,0,0],async()=>send(20,64));click('#modal-close');
  await sample('GUI cut stays independent',[0,-12,0],async()=>input(slider('mid'),-12));mixer();await sample('boost change preserves cut',[0,-12,0],async()=>boost(12));await sample('tab reset preserves cut and restores6',[0,-12,0],async()=>click('#reset-settings'));click('#save-settings');await sample('GUI neutral restores mixture',[0,0,0],async()=>input(slider('mid'),0));
  mixer();boost(12);click('#save-settings');r.savedBoost=engine.eqBoost;
 }catch(e){r.errors.push({message:e.message,stack:e.stack});}
 finally{
  for(const d of state.decks)engine.pause(d);
  if(engine.recording){const blob=await engine.recordStop(),bytes=new Uint8Array(await blob.arrayBuffer());r.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};try{const b=await engine.ctx.decodeAudioData(bytes.buffer.slice(0));r.decoded={duration:b.duration,frames:b.length,sampleRate:b.sampleRate,channels:b.numberOfChannels};assert(b.numberOfChannels===2,'Expected stereo master');for(let c=0;c<2;c++)for(const v of b.getChannelData(c))assert(Number.isFinite(v),'Nonfinite whole recording');for(const test of r.cases)test.amplitudes=r.frequencies.map(hz=>[0,1].map(c=>amplitude(b.getChannelData(c),b.sampleRate,test.from,test.to,hz)));assert(r.cases[0].amplitudes.flat().every(v=>v>.003),'Baseline too quiet');for(const test of r.cases){test.measuredDB=test.amplitudes.map((channels,i)=>channels.map((v,c)=>20*Math.log10(v/r.cases[0].amplitudes[i][c])));test.maxError=Math.max(...test.measuredDB.flatMap((channels,i)=>channels.map(v=>Math.abs(v-test.expectedDB[i]))));test.passed=test.maxError<=.45;}assert(r.cases.length===18&&r.cases.every(c=>c.passed),'Expected18 passing declared EQ windows');r.audioPassed=true;}catch(e){r.errors.push({message:e.message,stack:e.stack});}}
  r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.recordedAt=new Date().toISOString();output(r);sessionStorage.setItem('eq-boost-report',JSON.stringify(r));$('#eq-reload').hidden=false;
 }
}
$('#eq-run').onclick=run;$('#eq-reload').onclick=()=>{sessionStorage.setItem('eq-boost-reload','yes');location.reload();};
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'Actual app');app=window.openPlay;
 if(sessionStorage.getItem('eq-boost-reload')==='yes'){sessionStorage.removeItem('eq-boost-reload');const r=JSON.parse(sessionStorage.getItem('eq-boost-report'));r.sourceReload=await identities();r.reload={boost:app.engine.eqBoost,preference:app.state.settings['EQ Boost'],maxima:[...document.querySelectorAll('[data-mix]')].filter(e=>/:(low|mid|high)$/.test(e.dataset.mix)).map(e=>Number(e.max)),stopped:app.state.decks.every(d=>!d.playing)};r.completed=r.audioPassed&&r.sourceStable&&JSON.stringify(r.sourceReload)===JSON.stringify(r.sourceBefore)&&r.reload.boost===12&&r.reload.preference==='12 dB'&&r.reload.maxima.length===6&&r.reload.maxima.every(v=>v===12)&&r.reload.stopped&&!r.errors.length;r.finishedAt=new Date().toISOString();output(r);click('[data-panel="settings"]');click('[data-settings-tab="Mixer"]');}
 else{$('#eq-run').disabled=false;$('#eq-status').textContent='Ready for one recorded EQ workflow';}}
boot().catch(e=>$('#eq-status').textContent=e.message);
